import {describe, it, expect} from 'vitest';
import {createChatOrchestrator} from './chatOrchestrator.js';
import type {OrchestratorHooks} from './chatOrchestrator.js';
import type {ChatSession} from '../types/session.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';
import {ToolRegistry} from './tools/registry.js';
import type {AIProvider, MessageChunk, SendMessageParams, UsageMetadata} from '../types/ai.js';

const SENT_AT = '2026-01-01T00:00:00.000Z';

function createSession(content: string): ChatSession {
  return {
    sessionId: 's1',
    userId: 'u1',
    entries: [{role: 'user', content, timestamp: SENT_AT}],
  };
}

const STOP_DONE = {type: 'stop' as const, stopReason: 'end_turn'};
const STOP_FOR_TOOL = {type: 'stop' as const, stopReason: 'tool_use'};
const TOOL_CALL = {type: 'tool_use' as const, toolCall: {id: 'c1', name: 'test_tool', input: {}}};

describe('afterModelResponse usage reporting', () => {
  const promptBuilder = new PromptBuilder({identity: 'test'});
  const registry = new ToolRegistry();
  registry.register({
    definition: {name: 'test_tool', description: 'desc', inputSchema: {type: 'object'}},
    execute: async () => ({result: 'result', clientMessages: [], suppressAssistantResponse: false})
  });

  const scriptedProvider = (rounds: MessageChunk[][]): AIProvider => {
    let round = 0;
    return {
      async *sendMessage(): AsyncGenerator<MessageChunk> {
        for (const chunk of rounds[round++] ?? []) yield chunk;
      },
      async generateStructured<T>(): Promise<T> {
        return {} as T;
      },
    };
  };

  it('reports usage covering every provider call in that turn when driven through two tool rounds', async () => {
    let reportedUsage: any;
    const hooks: OrchestratorHooks = {
      afterModelResponse: async (_session, _text, usage) => {
        reportedUsage = usage;
      }
    };

    const provider = scriptedProvider([
      [TOOL_CALL, {type: 'stop', stopReason: 'tool_use', usage: {inputTokens: 10, outputTokens: 20, totalTokens: 30}}],
      [TOOL_CALL, {type: 'stop', stopReason: 'tool_use', usage: {inputTokens: 15, outputTokens: 25, totalTokens: 40}}],
      [{type: 'text', text: 'done'}, {type: 'stop', stopReason: 'end_turn', usage: {inputTokens: 5, outputTokens: 5, totalTokens: 10}}],
    ]);

    const orchestrator = createChatOrchestrator(provider, promptBuilder, registry, {hooks});
    await orchestrator.processMessage(createSession('ask'));

    // The hook should receive the sum of all rounds
    expect(reportedUsage).toMatchObject({
      inputTokens: 30, // 10 + 15 + 5
      outputTokens: 50, // 20 + 25 + 5
      totalTokens: 80, // 30 + 40 + 10
    });
  });

  it('a provider that reports no usage on some rounds does not make the total undefined or NaN', async () => {
    let reportedUsage: any;
    const hooks: OrchestratorHooks = {
      afterModelResponse: async (_session, _text, usage) => {
        reportedUsage = usage;
      }
    };

    const provider = scriptedProvider([
      [TOOL_CALL, {type: 'stop', stopReason: 'tool_use', usage: {inputTokens: 10, outputTokens: 20, totalTokens: 30}}],
      [TOOL_CALL, STOP_FOR_TOOL], // No usage reported in this round
      [{type: 'text', text: 'done'}, {type: 'stop', stopReason: 'end_turn', usage: {inputTokens: 5, outputTokens: 5, totalTokens: 10}}],
    ]);

    const orchestrator = createChatOrchestrator(provider, promptBuilder, registry, {hooks});
    await orchestrator.processMessage(createSession('ask'));

    expect(reportedUsage).toMatchObject({
      inputTokens: 15, // 10 + 5
      outputTokens: 25, // 20 + 5
      totalTokens: 40, // 30 + 10
    });
  });

  it('a turn where nothing reported still reports nothing', async () => {
    let reportedUsage: any;
    const hooks: OrchestratorHooks = {
      afterModelResponse: async (_session, _text, usage) => {
        reportedUsage = usage;
      }
    };

    const provider = scriptedProvider([
      [TOOL_CALL, STOP_FOR_TOOL],
      [{type: 'text', text: 'done'}, STOP_DONE],
    ]);

    const orchestrator = createChatOrchestrator(provider, promptBuilder, registry, {hooks});
    await orchestrator.processMessage(createSession('ask'));

    expect(reportedUsage).toBeUndefined();
  });
});
